          <span class="issue-header__subtitle">Fill in the details below to create a new issue</span>
        </div>
      </div>
    </div>

    <div class="row q-col-gutter-md">
      <!-- Main content (left) -->
      <div class="col-12 col-md-8">
        <!-- Title & Description -->
        <div class="detail-card q-mb-md">
