<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { useDocNetIssueStore } from 'src/store/DocNet/docnet-issues.store';
import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { useDocNetMissionStore } from 'src/store/DocNet/docnet-missions.store';
import { storeToRefs } from 'pinia';
import AssigneePicker, { type AssigneeOption } from '../shared/AssigneePicker.vue';
import type { DocNetIssueCreate } from 'src/@types/docnet';
import { useUserStore } from 'src/store/User/user_details.store';

function formatLabel(value: string): string {
  return value
    .replace(/_/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

export default defineComponent({
  name: 'DocNetIssueCreate',
  components: { AssigneePicker },

  setup() {
    const issueStore = useDocNetIssueStore();
    const agentStore = useDocNetAgentStore();
    const missionStore = useDocNetMissionStore();
    const userDetailsStore = useUserStore();
    const { profiles } = storeToRefs(agentStore);
    const { missions } = storeToRefs(missionStore);
    return { issueStore, agentStore, missionStore, userDetailsStore, profiles, missions };
  },

  data() {
    return {
      saving: false,
      formData: {
        title: '',
        description: '',
        status: 'todo',
        priority: 'medium',
        assignee_id: '',
        reporter_id: '',
        mission_id: '',
        due_date: '',
        tagsString: '',
      },
    };
  },

  computed: {
    statusOptions() {
      return ['todo', 'in_progress', 'in_review', 'done', 'cancelled', 'error'].map((v) => ({
        label: formatLabel(v),
        value: v,
      }));
    },
    priorityOptions() {
      return ['critical', 'high', 'medium', 'low'].map((v) => ({
        label: formatLabel(v),
        value: v,
      }));
    },
    agentPickerOptions(): AssigneeOption[] {
      return this.profiles.map((p) => ({
        label: p.agent.name,
        value: p.agent.id,
        type: 'agent' as const,
        role: p.role,
        workload: p.workload_percent,
      }));
    },
    humanPickerOptions(): AssigneeOption[] {
      return [
        { label: 'Amier Haider', value: 'user-001', type: 'human' as const },
        { label: 'Sarah Mueller', value: 'user-002', type: 'human' as const },
      ];
    },
    missionSelectOptions() {
      return this.missions.map((m) => ({
        label: m.name,
        value: m.id,
      }));
    },
  },

  async mounted() {
    await Promise.allSettled([
      this.agentStore.fetchProfiles(),
      this.missionStore.fetchMissions(),
    ]);
    const userId = this.userDetailsStore.getUserDetailByKey('id');
    if (userId) {
      this.formData.reporter_id = String(userId);
    }
    this.$nextTick(() => {
      (this.$refs.titleInput as any)?.focus();
    });
  },

  methods: {
    async onSave() {
      if (!this.formData.title.trim()) return;

      const tags = this.formData.tagsString
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean);

      const payload: DocNetIssueCreate = {
        title: this.formData.title.trim(),
        description: this.formData.description.trim(),
        status: this.formData.status as any,
        priority: this.formData.priority as any,
        tags,
      };

      if (this.formData.assignee_id) {
        (payload as any).assignee_id = this.formData.assignee_id;
      }
      if (this.formData.reporter_id) {
        payload.reporter_id = this.formData.reporter_id;
      }
      if (this.formData.mission_id) {
        (payload as any).mission_id = this.formData.mission_id;
      }
      if (this.formData.due_date) {
        (payload as any).due_date = this.formData.due_date;
      }

      this.saving = true;
      try {
        await this.issueStore.createIssue(payload);
        this.$router.push('/doc-net/issues');
      } catch (error) {
        notify.error('Failed to create issue');
      } finally {
        this.saving = false;
      }
    },
  },
});
</script>

